INSERT INTO public.servidores (matricula, nome, cargo, status)
SELECT DISTINCT ON (matricula) matricula, nome, cargo, 'ativo'::public.servidor_status
FROM dados
WHERE matricula IS NOT NULL AND nome IS NOT NULL
ORDER BY matricula
ON CONFLICT (matricula) DO UPDATE SET
  nome = EXCLUDED.nome,
  cargo = EXCLUDED.cargo,
  status = 'ativo',
  updated_at = now();
